@spec tv_master_channel_spec  src=tests/specs/tv_master_channel_spec.lua  loc=492  cases=20
@exercises dataStore (h.ds), trackerManager (h.tm), trackerView (h.vm), editCursor (h.ec), midiManager (h.fm), clipboard (h.clipboard), commandManager (h.cmgr)
@surface   ds:assign, tm:rebuild, vm:setGridSize, ec:setPos, vm:hideExtraCol, ds:get, vm:addExtraCol, vm:toggleChannelMute, vm:toggleChannelSolo, vm:isChannelMuted, vm:isChannelSoloed, vm:isChannelEffectivelyMuted, ec:col, vm:setPaletteParam, vm:automateParam, vm:paramBinding, tm:freezeEligible, tm:freezeRegion, fm:dump, vm:rebuild, ec:extendTo, clipboard:collect, ec:selClear, clipboard:pasteClip, ec:selectChannel, vm:fxHostForEdit, vm:scroll, tm:addEvent, tm:flush, vm:ghostOverlay, vm:explodeEligible, cmgr:invoke, tm:getChannel
@harness   mk, r._state.projectTracks, r._state.projectItems

# Intent
  Channel 0 is the master channel: an fx-only strip left of channel 1, always carrying at
  least one column, so a global region is always addressable. The strip is view-built; the
  regions on it run on every MIDI channel. see docs/trackerView.md § Addressing a chain

# Helpers
  @fn injectGlobals(h, list)  @ 12-21
      -- Global regions are ordinary stored regions at chan 0; each entry overrides the defaults,
      -- and the uuid is positional ('fxr-1', 'fxr-2', ...), as tv_fx_region_spec does for channels.
  @fn colIdx(h, chan, type, cc)  @ 24-30
      -- The grid index of a channel's column of one type: lane 1 for a note column, cc number for a cc.
  @fn colsOn(h, chan)  @ 32-38

# Cases
  @case 'an empty document opens with the master fx strip as column 1'  [harness]  @ 45-60
  @case 'the strip sits left of channel 1'  [harness]  @ 64-72
  @case 'a global region renders in the master strip and on no MIDI channel'  [harness]  @ 78-93
  @case 'overlapping global regions pack into sibling columns on channel 0'  [harness]  @ 97-110
  @case 'hide refuses on the master strip'  [harness]  @ 116-129
  @case 'add-column refuses on the master strip'  [harness]  @ 133-147
  @case 'mute and solo refuse on the master strip'  [harness]  @ 151-165
  @case 'parameter automation refuses on the master strip'  [harness]  @ 169-184
  @case 'freeze refuses a global region'  [harness]  @ 188-201
  @case 'paste drops a region rebased onto the master channel'  [harness]  @ 206-232
  @case 'channel select stands, and a selection on the strip mints a global region'  [harness]  @ 238-251
  @case 'the caret opens on channel 1 lane 1, not on the strip'  [harness]  @ 257-269
  @case 'the strip stands through the first rebuild, before the pane has a width'  [harness]  @ 275-280
  @case 'a take swap brings the scroll home, so the strip stands left of the caret'  [harness]  @ 284-294
  @case 'a global region runs its chain on every MIDI channel in use'  [harness]  @ 303-320
  @case 'the caret on a global badge ghosts the chain on every channel it reaches'  [harness]  @ 329-354
  @case 'the fx-convert chord on a global badge explodes it onto the channels in use'  [harness]  @ 363-404
  @case 'a global chain reaching no channel declines, opening no undo block'  [harness]  @ 410-433
  @case 'explode refuses off the master strip, where the chord freezes instead'  [harness]  @ 439-460
  @case 'a global chain lights its curve on the target column of each channel it reaches'  [harness]  @ 466-489

